import ballerina/io;

type L0a record {| int v; |};
type L0b record {| string v; |};
type L1a record {| L0a|L0b f; int k; |};
type L1b record {| L0a|L0b f; string k; |};
type L2a record {| L1a|L1b f; int k; |};
type L2b record {| L1a|L1b f; string k; |};
type L3a record {| L2a|L2b f; int k; |};
type L3b record {| L2a|L2b f; string k; |};
type L4a record {| L3a|L3b f; int k; |};
type L4b record {| L3a|L3b f; string k; |};
type L5a record {| L4a|L4b f; int k; |};
type L5b record {| L4a|L4b f; string k; |};
type L6a record {| L5a|L5b f; int k; |};
type L6b record {| L5a|L5b f; string k; |};
type L7a record {| L6a|L6b f; int k; |};
type L7b record {| L6a|L6b f; string k; |};
type L8a record {| L7a|L7b f; int k; |};
type L8b record {| L7a|L7b f; string k; |};
type L9a record {| L8a|L8b f; int k; |};
type L9b record {| L8a|L8b f; string k; |};
type L10a record {| L9a|L9b f; int k; |};
type L10b record {| L9a|L9b f; string k; |};
type L11a record {| L10a|L10b f; int k; |};
type L11b record {| L10a|L10b f; string k; |};

public function main() {
    L11a|L11b x = {f: {f: {f: {f: {f: {f: {f: {f: {f: {f: {f: {v: 1}, k: 1}, k: 2}, k: 3}, k: 4}, k: 5}, k: 6}, k: 7}, k: 8}, k: 9}, k: 10}, k: 11};
    io:println(x is L11a);
}

